namespace sv_8516db8c756441349d772188e7cc59d2.Services;

/// <summary>
/// Scoped service that holds the current warehouse selection for a single user circuit.
/// Provides change notification so unrelated components can react to warehouse switches.
/// </summary>
public sealed class WarehouseStateService
{
    private string _currentWarehouseId = "WH-001";

    public string CurrentWarehouseId => _currentWarehouseId;

    public string CurrentWarehouseName =>
        AvailableWarehouses.TryGetValue(_currentWarehouseId, out var name) ? name : _currentWarehouseId;

    public static IReadOnlyDictionary<string, string> AvailableWarehouses { get; } =
        new Dictionary<string, string>
        {
            ["WH-001"] = "Warehouse A - Main Distribution",
            ["WH-002"] = "Warehouse B - East Coast",
            ["WH-003"] = "Warehouse C - West Coast",
            ["WH-004"] = "Warehouse D - Returns Processing",
        };

    /// <summary>
    /// Fired when the selected warehouse changes. Subscribers must marshal to their
    /// own synchronization context (InvokeAsync) before touching UI state.
    /// </summary>
    public event Func<Task>? OnWarehouseChanged;

    public async Task SetWarehouseAsync(string warehouseId)
    {
        if (_currentWarehouseId == warehouseId) return;
        _currentWarehouseId = warehouseId;

        if (OnWarehouseChanged is not null)
        {
            await OnWarehouseChanged.Invoke();
        }
    }
}

namespace sv_8516db8c756441349d772188e7cc59d2.Services;

/// <summary>
/// Scoped service that manages low-stock alert polling for a single user circuit.
/// Components subscribe to OnAlertCountChanged to be notified when fresh data arrives.
/// Polling is ref-counted: starts when the first component requests it, stops when the last unsubscribes.
/// </summary>
public sealed class InventoryAlertService : IDisposable
{
    private readonly WarehouseStateService _warehouseState;
    private readonly Random _random = new();

    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private int _subscriberCount;
    private int _currentAlertCount;

    public int CurrentAlertCount => _currentAlertCount;

    /// <summary>
    /// Fired when a new alert count is available. All subscribed components receive this,
    /// not just the one that triggered the poll.
    /// </summary>
    public event Func<Task>? OnAlertCountChanged;

    public InventoryAlertService(WarehouseStateService warehouseState)
    {
        _warehouseState = warehouseState;
        _warehouseState.OnWarehouseChanged += HandleWarehouseChangedAsync;
    }

    /// <summary>
    /// Simulates a database query for items below minimum stock levels.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Call when a component wants to start receiving poll updates.
    /// Starts the polling timer on the first subscriber.
    /// </summary>
    public void StartPolling()
    {
        _subscriberCount++;
        if (_subscriberCount == 1)
        {
            _cts = new CancellationTokenSource();
            _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
            _ = PollLoopAsync(_cts.Token);
        }
    }

    /// <summary>
    /// Call when a component no longer needs poll updates.
    /// Stops the polling timer when the last subscriber leaves.
    /// </summary>
    public void StopPolling()
    {
        _subscriberCount = Math.Max(0, _subscriberCount - 1);
        if (_subscriberCount == 0)
        {
            CancelPolling();
        }
    }

    /// <summary>
    /// Forces an immediate refresh (e.g., after a warehouse switch).
    /// </summary>
    public async Task RefreshAsync()
    {
        _currentAlertCount = await GetLowStockCountAsync(_warehouseState.CurrentWarehouseId);
        if (OnAlertCountChanged is not null)
        {
            await OnAlertCountChanged.Invoke();
        }
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        // Immediately fetch on start so subscribers don't wait 10s for first data.
        await RefreshAsync();

        try
        {
            while (await _timer!.WaitForNextTickAsync(ct))
            {
                await RefreshAsync();
            }
        }
        catch (OperationCanceledException)
        {
            // Expected on dispose/stop.
        }
    }

    private async Task HandleWarehouseChangedAsync()
    {
        if (_subscriberCount > 0)
        {
            await RefreshAsync();
        }
    }

    private void CancelPolling()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
        _timer?.Dispose();
        _timer = null;
    }

    public void Dispose()
    {
        _warehouseState.OnWarehouseChanged -= HandleWarehouseChangedAsync;
        CancelPolling();
    }
}

