@using sv_8516db8c756441349d772188e7cc59d2.Services
@inject WarehouseStateService WarehouseState
@implements IDisposable

<div class="warehouse-selector d-flex align-items-center gap-2">
    <label for="warehouse-select" class="text-nowrap fw-semibold small">📦 Site:</label>
    <select id="warehouse-select"
            class="form-select form-select-sm"
            value="@WarehouseState.CurrentWarehouseId"
            @onchange="OnWarehouseChangedAsync">
        @foreach (var wh in WarehouseStateService.AvailableWarehouses)
        {
            <option value="@wh.Key">@wh.Value</option>
        }
    </select>
</div>

@code {
    protected override void OnInitialized()
    {
        WarehouseState.OnWarehouseChanged += StateHasChangedAsync;
    }

    private async Task OnWarehouseChangedAsync(ChangeEventArgs e)
    {
        var newId = e.Value?.ToString();
        if (!string.IsNullOrEmpty(newId))
        {
            await WarehouseState.SetWarehouseAsync(newId);
        }
    }

    private Task StateHasChangedAsync()
    {
        return InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        WarehouseState.OnWarehouseChanged -= StateHasChangedAsync;
    }
}

@using sv_8516db8c756441349d772188e7cc59d2.Services
@inject InventoryAlertService AlertService
@implements IDisposable

<span class="alert-badge position-relative">
