    @if (AlertService.CurrentAlertCount > 0)
    {
        <span class="badge rounded-pill bg-danger position-absolute top-0 start-100 translate-middle">
            @AlertService.CurrentAlertCount
        </span>
    }
    else
    {
        <span class="badge rounded-pill bg-success position-absolute top-0 start-100 translate-middle">
            0
        </span>
    }
</span>

@code {
    protected override void OnInitialized()
    {
        AlertService.OnAlertCountChanged += OnAlertUpdatedAsync;
    }

    private Task OnAlertUpdatedAsync()
    {
        return InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        AlertService.OnAlertCountChanged -= OnAlertUpdatedAsync;
    }
}

