@page "/dashboard"
@using sv_8516db8c756441349d772188e7cc59d2.Services
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable
@rendermode InteractiveServer

<PageTitle>Dashboard - @WarehouseState.CurrentWarehouseName</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mb-4">
    <div class="card-header">
        <strong>@WarehouseState.CurrentWarehouseName</strong>
    </div>
    <div class="card-body">
        <h5 class="card-title">Low-Stock Alerts</h5>
        <p class="display-4">
            @if (AlertService.CurrentAlertCount > 0)
            {
                <span class="text-danger">@AlertService.CurrentAlertCount items below minimum</span>
            }
            else
            {
                <span class="text-success">All stock levels healthy</span>
            }
        </p>
        <p class="text-muted small">
            Polling every 10 seconds. Last checked: @_lastRefresh.ToString("HH:mm:ss")
        </p>
    </div>
</div>

<div class="alert alert-info">
    <strong>How this works:</strong> This page starts polling when you navigate here and stops when you leave.
    The sidebar badge also updates in real-time because both components subscribe to the same
    <code>InventoryAlertService</code> events. Switching warehouses in the top bar immediately
    refreshes the data for all subscribed components.
</div>

@code {
    private DateTime _lastRefresh = DateTime.Now;

    protected override void OnInitialized()
    {
        AlertService.OnAlertCountChanged += OnAlertUpdatedAsync;
        WarehouseState.OnWarehouseChanged += OnWarehouseChangedAsync;
        AlertService.StartPolling();
    }

    private Task OnAlertUpdatedAsync()
    {
        _lastRefresh = DateTime.Now;
        return InvokeAsync(StateHasChanged);
    }

    private Task OnWarehouseChangedAsync()
    {
        return InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        AlertService.OnAlertCountChanged -= OnAlertUpdatedAsync;
        WarehouseState.OnWarehouseChanged -= OnWarehouseChangedAsync;
        AlertService.StopPolling();
    }
}

